"""Check OpenSim marker IK against poses generated by the model."""

from pathlib import Path

import numpy as np
import opensim as osim
import pytest

from arm_joint_state import ArmMeasurement, OpenSimArmJointState


ROOT = Path(__file__).resolve().parents[3] / 'musculoskeletal_models'
MARKER_NAMES = ('shoulder', 'elbow', 'wrist', 'index_mcp', 'pinky_mcp')


def model_path(dof):
    return ROOT / f'tsm_hand_{dof}DOF' / f'tsm_{dof}DOF_arm26_hand_scaled.osim'


def model_landmarks(path, pose):
    model = osim.Model(str(path))
    state = model.initSystem()
    coordinates = model.getCoordinateSet()
    free = [coordinates.get(i) for i in range(coordinates.getSize())
            if not coordinates.get(i).get_locked()]
    for coordinate, value in zip(free, pose):
        coordinate.setValue(state, value, False)
    model.realizePosition(state)
    markers = model.getMarkerSet()
    locations = np.array([
        [markers.get(name).getLocationInGround(state)[axis] for axis in range(3)]
        for name in MARKER_NAMES
    ])
    return locations[1:] - locations[0]


@pytest.mark.parametrize('dof', [3, 4])
@pytest.mark.parametrize('depth_sign', [-1.0, 1.0])
def test_opensim_ik_tracks_successive_frames(dof, depth_sign):
    path = model_path(dof)
    arm = OpenSimArmJointState(path, depth_sign=depth_sign)
    poses = ([0.4, 1.1, 0.8], [-0.5, 1.5, 1.2]) if dof == 3 else (
        [0.4, 1.1, -0.4, 0.8], [-0.5, 1.5, 0.2, 1.2])
    for pose in poses:
        landmarks = model_landmarks(path, pose)
        camera = (landmarks @ arm.alignment) * [1, 1, depth_sign]
        points = np.zeros((133, 3))
        points[6] = [0.2, -0.1, 2.0]
        points[[8, 10, 117, 129]] = camera + points[6]
        fitted = arm.estimate_from_people([{'keypoints_3d': points.tolist()}])
        np.testing.assert_allclose(fitted, pose, atol=5e-4)
        np.testing.assert_allclose(model_landmarks(path, fitted), landmarks, atol=5e-4)


@pytest.mark.parametrize('mcp_index', [2, 3])
def test_both_mcp_markers_affect_the_fit(mcp_index):
    arm = OpenSimArmJointState(model_path(4), alignment=np.eye(3))
    landmarks = model_landmarks(model_path(4), [0.4, 1.1, -0.4, 0.8])
    original = arm.estimate(ArmMeasurement(*landmarks))
    landmarks[mcp_index] += [0.01, 0.0, 0.02]
    changed = arm.estimate(ArmMeasurement(*landmarks))
    assert np.linalg.norm(changed - original) > 0.01


def test_no_person_produces_no_joint_state():
    arm = OpenSimArmJointState(model_path(4))
    assert arm.estimate_from_people([]) is None


def test_failed_frame_keeps_previous_pose(monkeypatch):
    import arm_joint_state as core

    arm = OpenSimArmJointState(model_path(4), alignment=np.eye(3))
    previous = arm.previous.copy()
    landmarks = model_landmarks(model_path(4), [0.4, 1.1, -0.4, 0.8])

    class FailingSolver:
        def __init__(self, *args):
            pass

        def setAdvanceTimeFromReference(self, value):
            pass

        def setAccuracy(self, value):
            pass

        def assemble(self, state):
            raise RuntimeError('IK failed')

    native_solver = core.osim.InverseKinematicsSolver
    monkeypatch.setattr(core.osim, 'InverseKinematicsSolver', FailingSolver)
    assert arm.estimate(ArmMeasurement(*landmarks)) is None
    np.testing.assert_array_equal(arm.previous, previous)
    monkeypatch.setattr(core.osim, 'InverseKinematicsSolver', native_solver)
    np.testing.assert_allclose(
        arm.estimate(ArmMeasurement(*landmarks)), [0.4, 1.1, -0.4, 0.8],
        atol=5e-4)
